import{_ as t}from"./chunks/gather-evidence.CFBdlZLj.js";import{_ as a,o as r,c as o,ak as i}from"./chunks/framework.sV-XtlWr.js";const m=JSON.parse('{"title":"Your first failure, explained","description":"","frontmatter":{"title":"Your first failure, explained","lang":"en-US"},"headers":[],"relativePath":"first-failure.md","filePath":"first-failure.md","lastUpdated":1788681757000}'),n={name:"first-failure.md"};function s(l,e,h,u,d,c){return r(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="your-first-failure-explained" tabindex="-1">Your first failure, explained <a class="header-anchor" href="#your-first-failure-explained" aria-label="Permalink to &quot;Your first failure, explained&quot;">​</a></h1><p>You&#39;ve landed your first run (<a href="./getting-started.html">Getting started</a>) and one test is red. This page walks through reading it. Piwi lays a failing execution out <strong>diagnosis-first</strong> — one column, top to bottom: <em>what</em> broke, <em>why</em>, the evidence, then what to <em>do</em> — so you&#39;re not scrolling a trace hoping to spot the problem.</p><p>Open the failing test from the run page (click its row) to reach its <strong>execution page</strong>.</p><figure><img src="'+t+'" alt="A failing execution laid out diagnosis-first: the header, a one-line headline, the other clues, and one evidence card with tabs"><figcaption>One failing execution, read top to bottom: the headline, the clues, the evidence, and the fix.</figcaption></figure><h2 id="_1-the-headline-—-what-broke" tabindex="-1">1. The headline — what broke <a class="header-anchor" href="#_1-the-headline-—-what-broke" aria-label="Permalink to &quot;1. The headline — what broke&quot;">​</a></h2><p>The first line is a plain-English sentence built from the Playwright error, before you read a word of the raw error itself:</p><blockquote><p><code>getByRole(&#39;button&#39;, { name: &#39;Pay&#39; }) never became enabled — click timed out after 30 s</code></p></blockquote><p>Under it, one row of facts: <strong>why</strong> (a new regression, or just flaky, or passed on retry), <strong>since when</strong> (the first run this started failing, with the commit and author), how many <strong>other tests in this run</strong> share the same cause, and the <strong>owner</strong>. The verbatim error is one click away under <strong>Show raw error</strong> — Piwi never rewrites it, it only leads with a readable summary. That same headline names the test on the run page, in <a href="./notifications.html">alerts</a>, in the <a href="./ci.html#pull-request-feedback">pull-request comment</a>, and in your terminal, so you recognize it everywhere.</p><h2 id="_2-the-clues-—-why" tabindex="-1">2. The clues — why <a class="header-anchor" href="#_2-the-clues-—-why" aria-label="Permalink to &quot;2. The clues — why&quot;">​</a></h2><p>Below the headline is a short list of <strong><a href="./evidence.html#clues">clues</a></strong>: deterministic, rule-based findings correlated from the evidence — <em>no model runs</em>. Things like:</p><ul><li><em>&quot;GET /api/quote returned 504, 1.1 s before the failure&quot;</em></li><li><em>&quot;Element renamed — healing found it under a new identity&quot;</em></li><li><em>&quot;Page ended on /login, not /checkout&quot;</em></li></ul><p>Each clue carries a strength and a <strong>citation</strong> to the evidence it came from; click it and the page jumps to the proof. This is usually where the answer is.</p><h2 id="_3-the-evidence-—-see-it" tabindex="-1">3. The evidence — see it <a class="header-anchor" href="#_3-the-evidence-—-see-it" aria-label="Permalink to &quot;3. The evidence — see it&quot;">​</a></h2><p>One <strong>evidence card</strong> with tabs — <strong>Timeline, Screen, Source, Network, Console, State, Performance</strong> — opens on the tab the strongest clue points at. The one to know first is <strong>Timeline</strong>: it places the test&#39;s steps, console entries, network requests and backend logs on a single clock and marks the <strong>moment of failure</strong>, so &quot;console (1) / network (3)&quot; becomes <em>what the app was doing when the test gave up</em>. <strong>Screen</strong> holds the failure screenshot, the visual diff against the last green run, and the failure-time page state; <strong>Source</strong> shows the test source as a real call stack, so a failure inside a helper shows the helper.</p><div class="tip custom-block"><p class="custom-block-title">Most of this needs one file</p><p>The error, trace, headline and clustering work with the reporter alone. The console, network, Web Vitals, failure-time snapshot and locator healing come from the <a href="./capture-fixtures.html">capture fixtures</a> — one file in your test setup. If a tab is dimmed, that&#39;s usually why; it opens to say so.</p></div><h2 id="_4-the-fix-—-what-to-do" tabindex="-1">4. The fix — what to do <a class="header-anchor" href="#_4-the-fix-—-what-to-do" aria-label="Permalink to &quot;4. The fix — what to do&quot;">​</a></h2><p>At the bottom, the <strong>Fix</strong> card gathers what to do about it, each part shown only when it applies:</p><ul><li>a <strong><a href="./locator-healing.html">replacement locator</a></strong> when a locator broke, ranked by stability and in your suite&#39;s own style;</li><li>the <strong><a href="./ai-diagnosis.html">AI diagnosis</a></strong> summary, when you&#39;ve configured a model (optional, and grounded in your real diff);</li><li><strong>verify</strong> — re-run in CI, or run it locally — and the tests this failure blocked.</li></ul><p>The point is to leave with something to do, not just something to read.</p><h2 id="you-re-not-reading-it-alone" tabindex="-1">You&#39;re not reading it alone <a class="header-anchor" href="#you-re-not-reading-it-alone" aria-label="Permalink to &quot;You&#39;re not reading it alone&quot;">​</a></h2><p>This execution is one member of a <strong><a href="./failure-clusters.html">failure cluster</a></strong> — Piwi groups every test that failed for the same reason, so forty red tests become three problems you triage once. From the cluster you get the full <a href="./ai-diagnosis.html">fix plan</a>, the owner, and — once a later run passes every test it covers — <a href="./ai-diagnosis.html#did-the-fix-work">confirmation the fix held</a>.</p><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><a href="./evidence.html">Failure evidence</a> — the full reference for everything on this page</li><li><a href="./failure-clusters.html">Failure clusters &amp; the inbox</a> — triaging failures as groups</li><li><a href="./capture-fixtures.html">Capture fixtures</a> — the one file that unlocks the richer evidence</li><li><a href="./concepts.html">Core concepts</a> — run, execution, cluster, fingerprint, baseline</li></ul>',23)])])}const p=a(n,[["render",s]]);export{m as __pageData,p as default};
